def totalTime(n, directions):
    dp = [float('inf')] * (n+2)  # Initialize a DP array with infinity
    dp[0] = 0  # Position 1 is always asleep, so the dream duration is at 0

    last_sign = -1  # Last sign encountered, -1 for 'U' and 0 for 'D'
    for i in range(1, n+1):
        if directions[i-1] == 'U':
            if last_sign == 0:
                dp[i] = 0 + dp[i-1]  # Sailor turns to 'D', moving direction needs to match
            elif last_sign == 1:
                dp[i] = dp[i-1] + 2  # Sailor turns to 'D', lots of travel moves
            else:
                dp[i] = 0  # Sailors current direction is down, match up descending with future descending
        else:
            if last_sign == 1:
                dp[i] = dp[i-1] + 3  # Sailor turns to 'U', heading up only one (will translate as 'U') moves
            elif last_sign == 0:
                dp[i] = dp[i-1]  # Sailor turns to 'U', just useful for picking up the rest of the future downward
            else:
                dp[i] = dp[i+1] + 2  # Sailor turns to 'U', reverse travel that crossed direction

        last_sign = 1 if dp[i] > dp[i-1] else 0

    return dp[1:-1]  # Ignore starting positions of index zero and one since they were asleep

