        mv = self.lazy[x]
        self.lazy[x] = 0
        mid = (lx + rx) >> 1
        self.update(l, r, mv, x << 1, 0, mid)
        self.update(l, r, mv, x << 1 | 1, mid + 1, self.n)

    def query(self, L, R, x, lx=0, rx=None, range_overflow=False):
        if lx >= L and rx <= R:
            return self.tree[x]
        if range_overflow or (rx == None and lx >= R) or (lx + 1 >= L and rx < L):
            return 0
        mid = (lx + rx) >> 1
        low, high = 0, self.n
        return self.query(L, R, x << 1, lx, mid, mid != rx) + self.query(L, R, x << 1 | 1, mid, rx - 1, rx != mid) + len(deque(self.lazy))

class Solution:
    def solve(self, n, m, a):
        st = SegmentTree(n)
        for op, *pos in zip(a[0], *a[1:], st.n << 1):
            if op == 1:
                st.update(pos, pos, a[1], 1, 0, len(st.tree) - st.lazy[::-1])  # Update for shape change
            else:
                b, e = pos[0], pos[-1]  # Query for memory
                if (b * e) not in {i * j for i, j in st.lazy}:
                    st.update(e + 1, n, 0)
                cur_mem = st.query(b, e)
                yield cur_mem
                st.update(b - 1, e, 0)  # Store changed beads' shape changes in lazy column if it was modified, in future changes
                # Note the number of elements in our change.
                update_points = 0
                if (b + e) % 2:
                    update_points += 1
                if e == len(st.tree) - 1:
                    update_points += 1
                if b == 0:
                    update_points += 1  # Sometimes lazy carry is a column at the far right of tree
                for i in range(b - 1, -1, -1):  # Move all changed point into upper vector so lazy is getting pushed up
                    for j in range(len(st.lazy)):
                        p = st.lazy[j][i]
                        if p > update_points or (p == update_points and b - i == j):
                            if b - i < st.n >> 1:
                                st.lazy[j][b - i + st.n >> 1] += st.lazy[j][i]
                            st.lazy[j][i] = 0
                        elif p > 0:  # lazy carry over will be push into upper vector
                            st.lazy[j][i + 1] = p
                if e == len(st.tree) - 1:
                    update_points += 1  # Deque will contain how many changed beads it changes
                    st.lazy[update_points] = deque(st.lazy[update_points])
            st.lazy = st.lazy[::-1]  # Pushback needs to be done so lower layers has lazy for update_points
        st.lazy = st.lazy[::-1]  # Pushback needs to be done so lower layers has lazy for update_points

# Example usage:
