import sys

def is_distinct(m):
    """Check if the energy requirements are distinct."""
    return len(m) == len(set(m))

def min_spanning_tree_with_extra_edges(n, edges):
    """Find the minimum spanning tree with the extra edges."""
    from collections import defaultdict as dd
    from heapq import heapify, heappop
    tcp_graph = dd(lambda: [])
    for u, v, w in edges:
        tcp_graph[u].append((w, v))
        tcp_graph[v].append((w, u))
    shortest, extra_edges = [], {}
    heap = [(0, 1)]
    while heap:
        e, u = heappop(heap)
        if u not in shortest:
            shortest.append(u)
            extra_edges[u] = []
            for v, w in tcp_graph[u]:
                p = min(shortest, default=lambda: sys.maxsize, key=lambda x: (x, -(w - e)))
                extra_edges[u].append((p, v, w - e, w))
                heap = [(w - e, v) for (_, v, w - e, w) in heap if w - e >= p]
    return extra_edges

def find_min_transport_length(edges, extra_edges, e, mid):
    """Find the minimum transport length by trying to move all energy to one corridor."""
    ports = set()
    capacity = defaultdict(int)
    extra_e = {}
    for u, v, w in extra_edges:
        if e == w:
            ports.add(u)
        elif e < w:
            capacity[(u, v)] -= 1
            capacity[(v, u)] += 1
        else:
            extra_e[v] = (e - w, u)
    for u, v in edges:
        if e == extra_edges[u][v][0]:
            ports.add(u)
        elif e <= extra_edges[u][v][2]:
            capacity[(u, v)] -= 1
            capacity[(v, u)] += 1
            ports.add(u)
        else:
            extra_e[v] = (u, extra_edges[u][v][3])
    def dfs(node, visited, capacity, extra_ports):
        out_ports = node - visited
        if not out_ports:
            return True
        min_val = extra_ports
        if min_val == extra_ports:
            extra_ports = out_ports
        for u, v in extra_edges[node]:
            u, v = v, u
            if u not in visited and capacity[(u, v)] > 0 and dfs(ports - set([vis for _, vis, _, _ in extra_e[v]]), set(visited) | set([u]), capacity - capacity[(u, v)], min([extra_ports, extra_ports - out_ports | set([u])])):
                return True
        for u, v in extra_edges[node]:
            u, v = v, u
            if u not in visited and capacity[(u, v)] > 0 and dfs(min([node], ports - set([vis for _, vis, _, _ in extra_e[u]])), set(visited) | set([v]), capacity - capacity[(u, v)], min([extra_ports, min_val - 1])):
                return True
        return False
    return 1 + float('inf') if not dfs(set(ports), set(), dict(sorted(capacity.items())), [min(ports, sorted(extra_ports, reverse=True))]) else 0

def main():
    n, m = map(int, input().split())
    edges = [tuple(map(int, input().split())) for _ in range(m)]
    extra_edges = min_spanning_tree_with_extra_edges(n, edges)
    for u, v, e in edges:
        energy = 2 * min(find_min_transport_length([u, v], extra_edges, e, path) for path in [[[], u, v]]) + e
        print(energy)
    return

if __name__ == "__main__":
    main()
