from typing import List, Tuple

def levenshtein_distance(s: str, t: str) -> int:
    m, n = len(s), len(t)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    for col_offset in range(1, m + 1):
        for row_offset in range(1, n + 1):
            cost = 0 if s[row_offset - 1] == t[col_offset - 1] else 1
            dp[col_offset][row_offset] = min(dp[col_offset][row_offset - 1] + 1, dp[col_offset - 1][row_offset] + cost,
                                            dp[col_offset - 1][row_offset - 1] + cost)

    return dp[n][m]

def min_cost_split(arr: List[int], k: int) -> int:
    n, total_splits = len(arr), k
    arr.sort(reverse=True)
    cost_matrix = [[int(x != y) for x in arr] for y in arr]

    # Calculate the number of subsequences for each substring
    subsequences = []
    current_subsequence = []
    for i in range(n):
        if not current_subsequence or arr[i] == current_subsequence[0]:
            current_subsequence.append(arr[i])
        else:
            if len(current_subsequence) > 1:
                subsequences.append(current_subsequence)
                current_subsequence = [arr[i]]
        if len(current_subsequence) > 1:
            subsequences.append(current_subsequence)
            current_subsequence = []

    # Calculate cost for each split
    cost = float('inf')
    for split_indices in itertools.product(range(1, total_splits), repeat=len(subsequences)):
        total_cost = 0
        for i, split in enumerate(split_indices):
            for j in range(subsequences[split_indices.index(split) - 1][len(subsequences[i]) - 1], subsequences[i - 1][0] - 1, -1):
                total_cost += cost_matrix[j][i + 1]
            for j in range(subsequences[i - 1][0], subsequences[i][0] - 1, -1):
                if j < len(subsequences[i]):
                    total_cost += cost_matrix[len(subsequences[i])][j + 1]
        cost = min(cost, total_cost)

    return cost
