def partition_cyclic_palindrome(s: str) -> int:
    MOD = 10**9 + 7
    even_palindrome_length = 2
    palindrome_length = (len(s)-1) // even_palindrome_length + 1
    dp = [1] + [0] * palindrome_length + [1]

    for length in range(4, palindrome_length + 1, 2):
        for i in range(palindrome_length + 1 - length, length - 1):
            dp[length] = (dp[length] + dp[i] * (2 if s[i] == s[-1 - (length - 1 - i)] else 1)) % MOD

    for i in range(1, palindrome_length - 1, 2):
        dp[i] = (dp[i] * 2-2) % MOD

    return dp[palindrome_length] % MOD

