            code = 0
            for j in range(len(word)):
                code = code * 26 + self.letters[word[j]]
                numerator, denominator = divmod(code, 998244353)
                self.letters_positions[code] = j
                self.counts[i + j][-i] = (numerator, denominator)

    def solve(self, m: int):
        ans = self.letters_positions[0] % MOD
        for i in self.counts:
            # check for letters covered already, avoid taking common above and below itself
            not_used_letters = set()
            for j in range(m):
                j = j % 26
                if i - j in self.counts[i] and (not j or not_used_letters & {j - i, i + j}):
                    not_used_letters = not_used_letters.union(set(range(i - j, i + j + 1)))
            else:
                num_numerator, num_denominator = self.counts[i][-i]
                den_numerator, den_denominator = self.counts[i + m - j][-i - m + j]
                num = (num_numerator * num_denominator + 
                       num_numerator * den_denominator * pow(den_numerator, -1, MOD)) % MOD
                num %= MOD
                den_mul = den_denominator * pow(num_denominator, -1, MOD)
                den_res = den_numerator // den_mul % MOD
                num_res = den_denominator * num // den_mul % MOD
                num %= MOD
