def convex_hull(p1, p2):
    hull = []
    i, j = 0, 1
    found = False
    while (i < len(p1) or j < len(p2)):
        if i >= len(p1):
            for x in p2[:j]:
                hull.append(x.values())
            return hull
        elif j >= len(p2):
