def count_good_partitions(n, pairs):
    dp = [[0] * n for _ in range(n+1)]
    for i, (s, f) in enumerate(pairs):
        dp[i+1][s] += 1
        dp[i+1][f] -= 1
    dp = [0] + dp + [0]
    inversions = [(i, j) for i in range(n) for j in range(i+1, n)]
    dp = [sum(dp[i]) for i in range(n+1) and inversions]

    def power(a, n):
        return pow(a, n, MOD)

    def inverse(a):
        return pow(a, MOD - 2, MOD)

    dp = map(inverse, dp)
    dp = map(lambda i: power(int(pow(dp[i], 2)), MOD - 2), range(n))
    dp = map(lambda i: (dp[i] + power(dp[i], MOD - 2) * dp[-1] % MOD) % MOD, range(n))

    return sum(dp) % MOD
