from collections import Counter

def minimum_cost_array(arr, k):
    counter = Counter(arr)
    # Sort the array in descending order to group the same element together
    sorted_arr = sorted(counter.items(), key=lambda x: (-x[1], x[0]))

    def backtrack(start, remaining_k):
        if remaining_k == 0:
            return 0
        if count == start:
            return float('inf')

        memoized = (start, remaining_k)
        if memoized in dp:
            return dp[memoized]

        min_cost = float('inf')
        for end in range(start, len(counter)):
            cost = -1 * counter[(sorted_arr[end+1][0], sorted_arr[end+1][1])]
            if cost > 0:
                min_cost = min(min_cost, backtrack(end + 1, remaining_k - 1) + cost)
        dp[memoized] = min_cost
        return min_cost

    n = len(sorted_arr)
    dp = {}
    count = n
    min_cost = -float('inf')
    for i in range(n - 1):
        current_cost = -1 * counter[(sorted_arr[i][0], sorted_arr[i][1])]
        if current_cost > 0:
            if (sorted_arr[i+1][0], sorted_arr[i+1][1]) == ('', '') and count < k:
                min_cost = current_cost + backtrack(i + 1, k - 2)

            min_cost = min(min_cost, current_cost + backtrack(i + 1, k - 1))
        if current_cost < 0:
            min_cost = min(min_cost, backtrack(i + 1, k - 1))
        count -= 1

    return int(min_cost)

