from math import comb, pow

def is_even(n):
    return n % 2 == 0

def k_beautiful_permutations(s):
    n = len(s)
    if not is_even(n):
        return 0

    dp = [0] * (n+1)
    factorial = [1] * (n+1)
    for i in range(2, n+1):
        factorial[i] = factorial[i-1] * i % 1000000007

    for cnt in range(1, n+1):
        total = factorial[cnt] * comb(n, cnt) % 1000000007
        for step in range(1, cnt):
            if (s[step-1] == s[-step]) or (s[step-1] != s[-step]):
                dp[step] = (2 * total - dp[step-1] * factorial[-step-1] % 1000000007 - dp[-1 * step-1]) % 1000000007
            else:
                dp[step] = total - dp[step-1]
        dp[cnt] = pow(2, dp[cnt-1], 1000000007)

    return dp[n]

