                for j in range(1, min(length // 2, k // 2) + 1):
                    left = dp[k-j][j-1] % MOD
                    mid = (dp[k-j][k-j+1] * dp[j][j]) % MOD
                    right = (dp[k-j][k-j+1] * dp[k-j+1][k-j]) % MOD

                    if j < min(length // 2, k // 2):
                        if j % 2 == 0:
                            dp[k][length] += left
                        else:
                            dp[k][length] = (dp[k][length] - left + MOD) % MOD

