    from collections import deque
    path = deque()
    visited = set()
    queue = collections.deque([(node_val, 0)])

    while queue:
        node, path_length = queue.popleft()

        if node == target_val:
            if path_length == 0:
                return len(visited.union(path))
            path.appendleft(lowest_common_ancestor(tree, node, target_val))

        visited.add(node)
        path.append(node)
        if path_length % 2 == 1:
            for child in tree[node].children:
                if child not in visited:
                    queue.append((child, path_length+1))

    return 0

# Lowest Common Ancestor (ancestor of path length pos)
def lowest_common_ancestor(tree, node_a, node_b):
    node_a_positions = {}
    while node_a is not None:
        if node_a.val not in node_a_positions:
            node_a_positions[node_a.val] = node_b
        node_a = node_a.children[-1]

    queue = deque([node_b.val])
    while queue:
        node = queue.popleft()
        while node is not None:
            if node.val in node_a_positions:
                return node
            else:
                queue.append(node)

    return None

