from collections import defaultdict
from heapq import heappop, heappush

def can_construct(a, rules):
    graph = defaultdict(list)
    for pos1, t1, pos2, t2 in sorted(rules):
        for i in range(len(a) - pos2 + 1):
            graph[i].append((pos1 + i, t1))
            if t1 == 'V':
                graph[i].append((pos2 + i, t2))
    for i, t in graph[-1]:
        if a[i] != 'C':
            return False
    for i, t in graph[-2]:
        if a[i] != 'V':
            return False
    return True

def construct_word(rules, current, size, a):
    heap = []
    heapq.heappush(heap, (0, -1))
    visited = set()
    while heap:
        cScore, pos = heapq.heappop(heap)
        if size == pos + 1:
            break
        if a[pos] == 'V':
            for i in range(len(a)):
                if (i, a[pos]) not in visited:
                    visited.add((i, a[pos]))
                    if a[i] != 'C':
                        visited.add((i, 'V'))
                    newScore = heap[0][0] + 1
                    heapq.heappush(heap, (newScore, pos+1))
        else:
            for i in range(len(a)):
                if (i, a[pos]) not in visited:
                    visited.add((i, a[pos]))
                    if a[i] != 'V':
                        visited.add((i, 'C'))
                    newScore = heap[0][0] + 1
                    heapq.heappush(heap, (newScore, pos+1))
    return heap[0][1], cScore + len(a) - size + 1

def find_min_word(a, n, m, rules, s):
    a = list(a)
    canConstruct = can_construct(a, rules)
    if not canConstruct:
        return "-1"
    heap = []
    heapq.heappush(heap, (0, 0, s, 0))
    visited = set()
    while heap:
        lScore, curPos, aPos, len = heapq.heappop(heap)
        if curPos == n:
            continue
        shifted = max(len, 1)
        if len >= n - 1:
            if aPos == n and lScore == 0:
                return s
            score = n-1 - len + 2 - shifted
        if not (a[(curPos + shifted) % n] == 'C' and (curPos + shifted) % n != len):
            continue
        if ((curPos, aPos)) not in visited:
            visited.add((curPos, aPos))
            rLen, rScore, cLen = 0, 0, 0
            for pos in range(len):
                pt1, pt2, pos1, pos2 = rules[pos - (len - 1)]
                if aPos == pt1 and curPos == pos2:
                    continue
                if curPos < pos2:
                    rLen -= 1
                if p1 < pos < p2:
                    rScore += 1
                rLen += 1
                if aPos == pos2 and curPos != pos1:
                    rScore -= 1
                cLen += 1
            newScore = (
                rScore + (len * len) // 2 -
                (min(len, n - 1) + (n - len + 1) * 2 // 2)
                + ((rLen * 2 + len * 2) - (rLen if rScore == 0 else 0))//len -
                ((cLen * 2) if cScore == 0 else cLen * 2)
            )
            if newScore >= lScore:
                if aPos != len + shifted or curPos - len < 0:
                    newScore += shifted
                if newScore >= lScore:
                    rLen, cLen = (n - curPos - 1, len - aPos)
                if rLen < cLen:
                    _, l_heaper = heapq.heappop(heap)
                    heapq.heappush(heap, (newScore, curPos + 1, aPos, 0))
                elif rLen > cLen:
                    _, h_heaper = heapq.heappop(heap)
                    heapq.heappush(heap, (newScore, curPos + 1, aPos, rLen - cLen))
                    _, h2 = heapq.heappop(heap)
                    if h2[0] >= h_heaper[1]: break
                    heapq.heappush(heap, h2)
        continue
    return "-1"

