def is_vowel(s):
    return s == 'V'

def is_consonant(s):
    return not is_vowel(s)

def apply_rule(rule1, rule2):
    return (rule1 == 'V' and rule2 == 'C') or (rule1 == 'C' and rule2 == 'V')

def get_prefix(tail, n):
    if len(tail) != n:
        return None
    freq = [0]*2
    for c in tail:
        freq[int(c) - int('A', 32)] += 1
    word = ""
    for i in range(3):
        if freq[i] == 0:
            word += 'A' + str(i+1)
        else:
            word += chr(97+(35-26-i)%26)
    return word

def is_leq(s1, s2):
    return all(s1[i] <= s2[i] for i in range(len(s1)))

def find_smallest_word(l, n, m, rules, s):
    vowels = [i for i, c in enumerate(s) if is_vowel(c)]
    words = []
    for i in range(1, 1 << len(vowels)):
        word = ""
        for j in range(len(vowels)):
            if i & 1 << j:
                word += 'A' + str(int(s[vowels[j]]) + 1)  # Convert to current vowel
        words.append(word)

    for rule in rules:
        word1 = words[(1 << rule[0] - 1) | (1 << rule[1] - 1)]
        word2 = words[(1 << rule[2] - 1) | (1 << rule[3] - 1)]
        word_same = float('-inf')
        if is_vowel(word1[0]) != is_vowel(word2[0]):
            if is_vowel(word1[0]):
                word_x = apply_rule([word2[0], is_consonant, word1[2], is_consonant])
                if word_x is not None:
                    word_x = apply_rule([word_x[0], is_vowel, word_x[2], is_vowel])
            else:
                word_x = apply_rule([word2[1], is_consonant, word1[1], is_vowel])
                if word_x is not None:
                    word_x = apply_rule([word_x[0], is_vowel, word_x[1], is_vowel])
        else:
            word_x = word1

        if word_x is not None and len(word_same) < len(word_x) or not word_same:
            word_same = word_x

    min_word = ''
    for word in words:
        if is_leq(word, s) and (min_word == '' or word <= min_word):
            min_word = word

    if min_word == '':
        min_word = "-1"
    return min_word

