def stairs_dream_duration(n, directions):
    if n == 1:
        return [0]

    direction_history = [0] * (n + 1)
    position = 1
    current_duration = 0

    for step in directions:
        direction_history[position] += 1
        direction = step if direction_history[step+1] % 2 != 0 else 'D' * (direction_history[step+1] - 1)

        # Calculate the duration of the dream
        to_left = max(0, position - 1)
        to_right = min(n, position + 1)
        if direction == 'U':
            to_left = 0
        elif direction == 'D':
            to_right = n

        duration = to_left + to_right + 1

        # Updating direction history for the next step
        if current_duration == 0 and direction_history[position] % 2 != 0:
            direction_history[position + 1] += 1
            if direction_history[position + 1] % 2 == 0:
                end_position = position + 1
        else:
            direction_history[position + 1] -= 1
            if direction_history[position + 1] < 0:
                end_position = position + 1

        if position == end_position:
            return
        position = end_position
        current_duration = duration
        if position == 1:
            return [current_duration]

        if direction_history[position+1] > 0:
            direction_history[position+1] -= 1

    return None

