def catalan_number(n):
    if n == 0:
        return 1
    else:
        return (2 * (2 * n - 1) * catalan_number(n - 1)) // (n + 1)

def partition_count(s):
    palindrome_counter = {x: 0 for x in s}
    for char in s:
        palindrome_counter[char] += 1

    count = 0
    for char in palindrome_counter:
        count += palindrome_counter[char] * palindrome_counter[char]

    return count // 2

def partition_string(s):
    n = len(s)
    partition_count_sum = [0] * (n + 1)
    palindrome_count_sum = [0] * (n + 1)

    for i in range(1, n + 1):
        partition_count_sum[i] = (
            partition_count_sum[i - 1] +
            partition_count(s[0:i])
        )
        palindrome_count_sum[i] = (
            palindrome_count_sum[i - 1] +
            palindrome_count(s[0:i]) * 2 - 2
        )

    return partition_count_sum[n] * (catalan_number((n + 1) // 2)) % (10**9 + 7)

