import sys

def search_longest_sequence(pattern, text):
    n = len(pattern)
    m = len(text)
    pi = [-1] * n
    j = -1
    for i in range(1, n):
        while j >= 0 and pattern[j % n] != pattern[i]:
            j = pi[j]  # Rolling hash along the pattern
        if pattern[j % n] == pattern[i]:
            pi[i] = j + 1
            j += 1

    pi = [-1] * (m + 1)
    for i in range(min(n, m), -1, -1):
        while j >= 0 and text[i + 1] != pattern[j % n]:
            j = pi[j]  # Rolling hash along the text
        if text[i + 1] == pattern[j % n]:
            pi[j + 1] = j + 1
            j += 1

    return pi

def find_starts_or_ends(text, pattern):
    n, m = len(text), len(pattern)
    pi = search_longest_sequence(pattern, text)
    result = set()
    i, j = 0, 0
    for i in range(n):
        while j <= m and (not i > m or pattern[j] == text[i]):
            if j == m or i >= m:
                result.add(i - j + 1)
            j += 1
    return result

def solve(instructions):
    result = []
    visited = [False] * (len(instructions) + 1)
    for i, direction in enumerate(instructions):
        duration = 0
        while not visited[i] and i < len(instructions):
            visited[i] = True
            duration += 1
            duration += (i == 0) * (-1) + direction == 'U'  # Up (or down if we fall)
            i = (i + 1) % len(instructions)
        result.append(duration)

    return result

