# Program to answer problems on Euler Tour
def eulerTour(n, tree, start_i, query_array):
    # Build adjacency tree
    adj_mat = defaultdict(list)

    for i in range(n):
        adj_mat[start_i[i]] = []

    for ar in tree:
        adj_mat[ar[0]].append(ar[1])
        adj_mat[ar[1]].append(ar[0])

    result = []
    # Main function to solve queries
    def answer_q(k, r, tup):
        return dfs(r, -1, adj_mat)

    for k, r, *nodes in query_array:
        nodes = list(dict.fromkeys(nodes))  # Remove duplicates
        if len(nodes) == 0:
            continue
        if len(nodes) < k:
            result.append(0)
            continue
        subset_map = {}
        for node in nodes:
            if node not in subset_map:
                subset_map[node] = len(result) 

        starters = deque(start_node(i) for i in range(len(nodes)))
        successors = defaultdict(set)

        for all in (2, 1):
            curr = starters if (all == 1) else answer_q(k, 0, all)
            subtree_size = len(curr)
            while subtree_size > all:
                remove_from_deque(curr, curr[all])
                successors[curr[all]].update(curr)
                curr = curr[all]
                if curr == starters:
                    starters = deque(start_node(i) for i in range(len(nodes)))
                    break

        for i, nxt in enumerate(successors):
            if len(subset_map[nxt]) == 1:
                result.append((intersect(subset_map[nxt].pop(), nodes)))
    # Printing answer on stdout
    print(" ".join([str(x) for x in result]))


