from collections import defaultdict

def process_changes(changes, old_shapes):
    shape_index = defaultdict(int)
    for i, shape in enumerate(old_shapes):
        shape_index[shape] = i

    updated_shapes = list(old_shapes)
    def update_changes(p, new_shape):
        nonlocal updated_shapes
        index = shape_index.get(new_shape)
        if index is not None and index != old_shapes[p]:
            updated_shapes[p] = new_shape
            changes.append([1, p+1, new_shape])

    for change in changes:
        old_value, p, new_value = change
        if old_value != new_value:
            update_changes(p-1, new_value)
            if old_value != 0:
                update_changes(p-1, 0)
        else:
            update_changes(p-1, old_value)

def query_memory(l, r, old_shapes):
    shape_index = defaultdict(int)
    for i, shape in enumerate(old_shapes):
        shape_index[shape] = i

    cur_shapes = deepcopy(old_shapes)
    def get_memory(start, end):
        local_index = shape_index.get(cur_shapes[start])
        if local_index is not None and local_index != start-1:
            cur_shapes[start-1] = 0
            l[q] -= cur_shapes[start-1]
        if local_index is not None and local_index != end-1:
            cur_shapes[end-1] = 0
            r[q] -= cur_shapes[end-1]
        r[q] += get_memory(start, start+1) + get_memory(end-1, end)
        return cur_shapes[start] if local_index in {start-1, start, end-1, end} else 0

    get_memory(l-1, r)
    return r[q]

