from typing import List

def max_weight_sum(n: int, points: List[List[int]], weights: List[int]) -> int:
    # Sort points based on x, then y
    sorted_points = sorted(points)
    max_sum = 0

    # Initialize a dictionary to keep track of potential important points
    important_points = {}

    for x, y in sorted_points:
        # Skip odd y values as they don't form important tents
        if y % 2:
            continue
        # Skip previously removed points from even x
        if sorted_points.index((x-1, y)) >= 0:
            continue
        # Skip previously removed points that lied too close to current one
        if sorted_points.index((x-2, y)) >= 0:
            continue

        count = 0
        for i in range(n):
            while count < 4 and i < n:
                if abs(sorted_points[i][0] - x) <= 1 and abs(sorted_points[i][1] - y) <= 1:
                    i += 1
                    continue
                count += 1
        if count < 4:
            continue

        tent_sum = sum(w for x1, y1, w in weights if abs(x - x1) <= 1 and abs(y - y1) <= 1)
        if tent_sum <= max_sum:
            important_points[tent_sum, x, y] = []
            continue
        _important_points = []
        for i in range(n):
            if abs(sorted_points[i][0] - x) <= 1 and abs(sorted_points[i][1] - y) <= 1:
                _important_points.append((abs(sorted_points[i][0] - x), abs(sorted_points[i][1] - y)))
        for _sum, _dx, _dy in _important_points:
            for pair in important_points.keys():
                if pair[2] == pair[0] or pair[2] == pair[1] - 1 or pair[2] == pair[1] + 1:
                    continue
                print(pair, [y1 for x1, y1, w in weights if abs(x1 - x) <= 1 and abs(y1 - y) <= 1], _sum, x, y)
                continue
        important_points[tent_sum, x, y] = _important_points
        if tent_sum > max_sum:
            max_sum = tent_sum

    return max_sum

