from collections import defaultdict

# Function to find the minimum cost of splitting the array
def find_min_cost(n, k, a):
    if n == 2:
        return 0   # Cost is zero if the array has 2 elements

    sorted_a = sorted(a)
    dp = defaultdict(int)
    prefix_sum = [0]

    # Create cumulative sum array
    for i in range(1, n+1):
        prefix_sum.append(prefix_sum[-1] + sorted_a[i-1])

    # Precompute longest common prefix sums (lcp) from sorted array
    lcp = [prefix_sum[-1]]
    max_count = 0
    for i in range(1, n+1):
        count = prefix_sum[-1] - prefix_sum[i]
        if count <= 2 * n:
            lcp.append(count)
        else:
            max_count = max(max_count, count - n - n + 1)

        for j in range(i - n + 1):
            lcp[j] -= count

    # Initialize DP table
    for i in range(1, k+1):
        dp[(i, -1)] = float('inf')

    dp[(k, -1)] = 0

    # Fill DP table
    for i in range(k, n+1):
        for j in range(i+1, n+1):
            avg = (j-i+1) / 2
            for c in range(n):
                ind1 = int((i-c-1) / avg)
                ind2 = int((j-c-1) / avg)
                # Only check if current elements are different
                if sorted_a[i-c-1] != sorted_a[j-c-1]:
                    delta = lcp[ind1] + lcp[
                        ind2
                    ] * 2  # sum exact overlaps and each half of here

                    if dp[(j, i)] > dp[(i, ind1)] + dp[(j, ind2)] + delta:
                        dp[(i, j)] = dp[(j, i)] + delta
                else:
                    if dp[(j, i)] > dp[(i, ind1)] + dp[
                        (j, ind2)
                    ] + 1:  # only one match
                        dp[(i, j)] = dp[(j, i)] + 1

            for c in range(max_count + 1):
                ind1 = int((i - c - 1) / avg)
                delta = c + lcp[ind1] * avg 

                if dp[(i, j)] > dp[(i, ind1)] + delta + 1:
                    dp[(i, j)] = dp[(i, j)] + delta + 1

    return int(dp[(n, 0)])  # Max(L he?)
