from math import inf

def is_pentagram(p, q, r, s):
    # Check if points are non-collinear
    return crossProduct(p, q, r) * crossProduct(p, q, s) < 1e-9

def crossProduct(a, b, c):
    return (b[0]-a[0])*(c[1]-a[1]) - (b[1]-a[1])*(c[0]-a[0])

def countPentagrams(points):
    count = 0

    for i in range(len(points)):
        first = points[i]
        for j in range(i+1, len(points)):
            sec = points[j]
            for k in range(j+1, len(points)):
                third = points[k]
                for l in range(l+1, len(points)):
                    fourth = points[l]
                    for m in range(m+1, len(points)):
                        fifth = points[m]
                        if is_pentagram(first, second, third, fourth) and is_pentagram(fifth):
                            count += 1

    return count

